import { test, expect } from '@playwright/test';

test.describe('Notification Click Navigation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/notifications');
  });

  test('should navigate to relevant content when clicking a notification', async ({ page }) => {
    // Verify notification is visible
    const notification = page.getByRole('alert');
    await expect(notification).toBeVisible();

    // Verify notification contains relevant content
    const notificationText = page.getByText('New message from John');
    await expect(notificationText).toBeVisible();

    // Verify navigation button is present
    const navButton = page.getByRole('button', { name: /view message/i });
    await expect(navButton).toBeVisible();

    // Click the navigation button
    await navButton.click();

    // Verify navigation route is correct
    const route = page.route('**/messages/123', route => {
      route.abort('Route intercepted');
    });

    await expect(route).toBeFired();

    // Verify content is displayed
    const messageContent = page.getByText('Message from John');
    await expect(messageContent).toBeVisible();

    // Verify navigation button is disabled
    await expect(navButton).toBeDisabled();
  });

  test('should handle multiple notifications and navigate to the last clicked one', async ({ page }) => {
    // Click first notification
    const firstNotification = page.getByRole('alert');
    await firstNotification.click();

    // Verify first notification is removed
    await expect(firstNotification).not.toBeVisible();

    // Click second notification
    const secondNotification = page.getByRole('alert');
    await secondNotification.click();

    // Verify second notification is visible
    await expect(secondNotification).toBeVisible();

    // Verify navigation button is present
    const navButton = page.getByRole('button', { name: /view message/i });
    await expect(navButton).toBeVisible();

    // Click the navigation button
    await navButton.click();

    // Verify navigation route is correct
    const route = page.route('**/messages/456', route => {
      route.abort('Route intercepted');
    });

    await expect(route).toBeFired();

    // Verify content is displayed
    const messageContent = page.getByText('Message from Jane');
    await expect(messageContent).toBeVisible();

    // Verify navigation button is disabled
    await expect(navButton).toBeDisabled();

    // Verify first notification is still visible
    await expect(firstNotification).toBeVisible();
  });
});
